// ── Build the Apify actor call from Whizz's search request ──
// NOTE: actorId and actorInput below are a best-effort guess at the 2GIS actor's real schema —
// see the Setup Notes sticky note. Adjust once you've confirmed the actor's actual Input tab.
// Swapped from thenetaji/2gis-place-scraper (a real test run confirmed it needs `placeIds` you
// don't have yet — it's a deep-enrichment-by-ID actor, not a search actor) to the sibling
// thenetaji/2gis-search-scraper, which searches by query+city directly and returns
// phone/website/rating in the same row — no second enrichment step needed for our case.
// No API token here — Call Apify 2GIS Actor authenticates via n8n's native Apify credential
// (Authentication: Predefined Credential Type → Apify API) instead of a token in code.
const body = $('Webhook').first().json.body || {};
const query = (body.query || [body.brand, body.category].filter(Boolean).join(' ')).trim();
const location = (body.location || '').trim();
// 2GIS result pages run well past 20 for broad categories/cities — raise the ceiling so a
// single run collects a meaningfully wider net than the old 50-item cap allowed.
const APIFY_2GIS_HARD_CAP = 100;
const limit = Math.max(1, Math.min(Number(body.limit) || 20, APIFY_2GIS_HARD_CAP));

const ACTOR_ID = 'thenetaji~2gis-search-scraper';

return [{
  json: {
    actorId: ACTOR_ID,
    actorInput: {
      queries: [query],
      cities: [location],
      maxItems: limit
    }
  }
}];

// ── Normalize the Apify dataset into what Whizz's Contact Discovery UI expects ──
// Defensive on field names for the same reason as Build Apify Request: unverified live.
const items = $input.all();
let rawItems = [];
let apiError = null;

for (const item of items) {
  const j = item.json;
  if (j && j.error) { apiError = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)); continue; }
  if (Array.isArray(j)) rawItems.push(...j);
  else if (j) rawItems.push(j);
}

if (apiError) {
  return [{ json: { contacts: [], error: `2GIS/Apify error: ${apiError}` } }];
}

// dedupe within a single run — the actor can repeat a listing across paginated result pages
const seen = new Set();
const contacts = [];
for (const it of rawItems) {
  const name = it.title || it.name || it.storeName || it.company || '';
  if (!name) continue;
  // stable per-listing id so Whizz can tell "already imported, refresh it" from "brand new"
  const sourceId = String(it.id || it.placeId || it.gisId || it['2gisId'] || it.fid || it.url || it.link || '').trim();
  const dedupeKey = sourceId || name.toLowerCase();
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);

  contacts.push({
    name,
    phone: it.phone || it.phoneNumber || it.phoneUnformatted || (Array.isArray(it.phones) ? it.phones[0] : '') || '',
    email: it.email || (Array.isArray(it.emails) ? it.emails[0] : '') || '',
    website: it.website || it.domain || it.url_website || '',
    address: it.address || it.full_address || it.location || '',
    city: it.city || it.district || '',
    countryCode: it.countryCode || it.country || '',
    categoryName: it.category || it.rubric || (Array.isArray(it.categories) ? it.categories[0] : '') || '',
    totalScore: it.totalScore || it.rating || it.stars || 0,
    url: it.url || it.link || it.placeUrl || it.googleMapsUrl || '',
    sourceId
  });
}

return [{ json: { contacts } }];
